source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid colored edge marks the direction of gravity.
    marker = None
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            marker = (row[0], "horizontal", r)
            break
    if marker is None:
        for c in range(w):
            v = grid[0][c]
            if v != 0 and all(grid[r][c] == v for r in range(h)):
                marker = (v, "vertical", c)
                break
    if marker is None:
        return [row[:] for row in grid]
    color, axis, idx = marker
    cells = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != 0 and not (grid[r][c] == color and ((axis == "horizontal" and r == idx) or (axis == "vertical" and c == idx)))}
    objects = []
    while cells:
        start = next(iter(cells))
        val = grid[start[0]][start[1]]
        stack = [start]
        comp = set()
        cells.remove(start)
        while stack:
            r, c = stack.pop()
            comp.add((r, c))
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and grid[q[0]][q[1]] == val:
                    cells.remove(q)
                    stack.append(q)
        objects.append((val, comp))
    dr, dc = ((-1,0) if axis == "horizontal" and idx == 0 else
              (1,0) if axis == "horizontal" else
              (0,-1) if idx == 0 else (0,1))
    # Process objects from the marked edge outward, letting each slide until blocked.
    def dist(obj):
        pts = obj[1]
        if dr < 0: return min(r for r,c in pts)
        if dr > 0: return -max(r for r,c in pts)
        if dc < 0: return min(c for r,c in pts)
        return -max(c for r,c in pts)
    objects.sort(key=dist)
    occupied = set()
    placed = []
    for val, comp in objects:
        cur = set(comp)
        while True:
            nxt = {(r+dr,c+dc) for r,c in cur}
            if any(r < 0 or r >= h or c < 0 or c >= w for r,c in nxt):
                break
            if nxt & occupied:
                break
            if any((axis == "horizontal" and r == idx) or (axis == "vertical" and c == idx) for r,c in nxt):
                break
            cur = nxt
        occupied |= cur
        placed.append((val, cur))
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r,c in (( (r,c) for r in range(h) for c in range(w))):
        if (axis == "horizontal" and r == idx) or (axis == "vertical" and c == idx):
            out[r][c] = color
    for val, comp in placed:
        for r,c in comp:
            out[r][c] = val
    return out
'''
